import{_ as i,a0 as r,w as l,s,ao as h,I as e,x as o,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"为什么 Linux 的 htop 命令完胜 top 命令 | LCTT x X-CMD","titleTemplate":false,"description":"为什么 Linux 的 htop 命令完胜 top 命令 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为什么 Linux 的 htop 命令完胜 top 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为什么 Linux 的 htop 命令完胜 top 命令 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/Why htop Command Compete Linux top Command","title":"为什么 Linux 的 htop 命令完胜 top 命令","tag":"201406","desc":""},"relativePath":"201406/Why htop Command Compete Linux top Command.md","filePath":"[post].md"}'),d={name:"201406/Why htop Command Compete Linux top Command.md"};function m(u,t,x,g,f,c){const p=r("Link");return l(),s("div",null,[t[11]||(t[11]=h('<h1 id="为什么-linux-的-htop-命令完胜-top-命令" tabindex="-1">为什么 Linux 的 htop 命令完胜 top 命令 <a class="header-anchor" href="#为什么-linux-的-htop-命令完胜-top-命令" aria-label="Permalink to “为什么 Linux 的 htop 命令完胜 top 命令”">​</a></h1><p>在 Linux 系统中，top 命令用来显示系统中正在运行的进程的实时状态，它显示了一些非常有用的信息，比如 CPU 利用情况、内存消耗情况，以及每个进程情况等。但是，你知道吗？还有另外一个命令行工具 &#39;htop&#39;，它与传统的 top 命令功能一样，但它有更加强大的功能及能显示更多的信息。这篇文章，我们会用实例来讨论这个 &#39;htop&#39; 命令。</p><h3 id="linux-中的-htop-命令" tabindex="-1">Linux 中的 htop 命令 <a class="header-anchor" href="#linux-中的-htop-命令" aria-label="Permalink to “Linux 中的 htop 命令”">​</a></h3><p>下面是从 htop 的手册页摘抄下来的相关描述:</p><blockquote><p>它类似于 top 命令，但可以让你在垂直和水平方向上滚动，所以你可以看到系统上运行的所有进程，以及他们完整的命令行。</p><p>可以不用输入进程的 PID 就可以对此进程进行相关的操作 (killing, renicing)。</p></blockquote><h3 id="首先明白它的输出" tabindex="-1">首先明白它的输出 <a class="header-anchor" href="#首先明白它的输出" aria-label="Permalink to “首先明白它的输出”">​</a></h3><p><strong>htop 命令</strong>以直观的格式来显示信息。下面是 HTOP 的输出快照:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/htop.png" alt="htop"></p><p>如果你观察窗口的左上角部分，你会看到显示的是 CPU 负载、内存消耗及交换空间的实时信息，右上角包含的是任务、线程、平均负载及系统运行时间的信息。</p><p>平均负载部分提供了三个数字，这仅仅表示的是过去的5分钟、10分钟和15分钟系统的平均负载而已，在单核的系统中，平均负载为1表示的是百分之百的 CPU 利用率。最后，运行时间 （uptime）标示的数字是从系统启动起到当前的运行总时间。</p><p>下面，我们将用例子来进一步讨论这个命令。</p><h3 id="_1-用-f2-键编辑配置" tabindex="-1">1. 用 F2 键编辑配置 <a class="header-anchor" href="#_1-用-f2-键编辑配置" aria-label="Permalink to “1. 用 F2 键编辑配置”">​</a></h3><p>htop 命令提供了许多自定义选项，你所要做的就是从主窗口中按下 F2 键。</p><p>下面所示的是可用的自定义选项:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/htop-settings.png" alt="htop-settings"></p><p>只需使用箭头键选择和更改特定的设置。</p><h3 id="_2-通过-f9-键发送信号" tabindex="-1">2. 通过 F9 键发送信号 <a class="header-anchor" href="#_2-通过-f9-键发送信号" aria-label="Permalink to “2. 通过 F9 键发送信号”">​</a></h3><p>htop 命令可以让你很容易地在 htop 窗口内给一个进程发送任意的信号。按下 F9 键即可。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/signals.png" alt="signals"></p><p>如你所见，窗口的左边部分列出的是所有可用的信号，右边部分列出的是进程。只要选中信号，并选择一个进程，然后按下 enter 键，选中的信号就会发送到此进程。</p><h3 id="_3-显示进程的树状视图" tabindex="-1">3. 显示进程的树状视图 <a class="header-anchor" href="#_3-显示进程的树状视图" aria-label="Permalink to “3. 显示进程的树状视图”">​</a></h3><p>htop 命令也提供了进程的树状视图查看功能。按下 F5 键切换。</p><p>下面是 htop 显示树形视图信息的例子:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/treeView.png" alt="treeView"></p><p>要退出树状视图模式，请再一次按下 F5 键。</p><h3 id="_4-通过-f3-键搜索进程" tabindex="-1">4. 通过 F3 键搜索进程 <a class="header-anchor" href="#_4-通过-f3-键搜索进程" aria-label="Permalink to “4. 通过 F3 键搜索进程”">​</a></h3><p>htop 命令提供了易用的方式来搜索进程。按下 F3 键，一个文本框就会出现在窗口底部。</p><p>下面是例子:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/search1.png" alt="search"></p><p>如您所见，一条名为‘搜索’的文本提示框出现在窗口底部，您可以在这儿输入进程的名字然后回车搜索。如果找到，它会在列出的进程列表里高亮选中此进程。</p><h3 id="_5-通过空格键来设置颜色标注进程条目" tabindex="-1">5. 通过空格键来设置颜色标注进程条目 <a class="header-anchor" href="#_5-通过空格键来设置颜色标注进程条目" aria-label="Permalink to “5. 通过空格键来设置颜色标注进程条目”">​</a></h3><p>在系统中运行着的实时进程视图中，要追踪某个进程是个大问题。因为整个列表在不停的刷新着，进程的排列顺序也在变动着。为了这个问题， htop 提供了一个很简单的解决方案：颜色标注。是的，你可以标注一个进程条目，它会以不同的颜色显示，因此要追踪它就变得容易了。</p><p>要标注某个进程条目，需要做的就是选中此条目，然后按下‘空格’键。例如，在下面的截图示例中，我已经颜色标注了三个进程条目:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/color-tag.png" alt="color-tag"></p><p>所以通过此方法，你就能很轻松地追踪想查看的进程。</p><h3 id="_6-命令行选项" tabindex="-1">6. 命令行选项 <a class="header-anchor" href="#_6-命令行选项" aria-label="Permalink to “6. 命令行选项”">​</a></h3><p>除了上面介绍的一些热键，htop 还提供了很有用的命令行选项。下面是其中一部分:</p><ul><li><strong>-s 选项</strong> : 按指定的列排序。例如，<strong>htop -s PID</strong> 命令会按 PID 列的大小排序来显示。</li><li><strong>-u 选项</strong> : 显示指定的用户的进程信息列表。例如，<strong>htop -u himanshu</strong> 命令会只显示出用户名为 himanshu 的相关进程。</li><li><strong>-d 选项</strong> : 设置刷新的延迟时间。例如，<strong>htop -d 100</strong> 命令会使输出在1秒后才会刷新（参数 -d 的单位是10微秒）。</li></ul><hr>',39)),e("p",null,[t[1]||(t[1]=o("via: ",-1)),a(p,{href:"http://linoxide.com/linux-command/linux-htop-command/"},{default:n(()=>[...t[0]||(t[0]=[o("http://linoxide.com/linux-command/linux-htop-command/",-1)])]),_:1})]),e("p",null,[t[4]||(t[4]=o("译者：",-1)),a(p,{href:"https://github.com/runningwater"},{default:n(()=>[...t[2]||(t[2]=[o("runningwater",-1)])]),_:1}),t[5]||(t[5]=o(" 校对：",-1)),a(p,{href:"https://github.com/carolinewuyan"},{default:n(()=>[...t[3]||(t[3]=[o("Caroline",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=o("本文由 ",-1)),a(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原创翻译，",-1)),a(p,{href:"http://linux.cn/"},{default:n(()=>[...t[7]||(t[7]=[o("Linux中国",-1)])]),_:1}),t[10]||(t[10]=o(" 荣誉推出",-1))])])}const _=i(d,[["render",m]]);export{T as __pageData,_ as default};
